toolArgs.file_text:
@namespace sv_2c2160ed52bb4f5a83b40b0d33140df4.Components.Chat

<div class="thread-panel">
    <div class="thread-header">
        <h3>Thread</h3>
        <button class="close-btn" @onclick="OnClose">✕</button>
    </div>

    <div class="root-message-quote">
        <span class="quote-author">@RootMessage.Author</span>
        <p class="quote-content">@RootMessage.Content</p>
    </div>

    <div class="thread-messages">
        @foreach (var reply in Replies)
        {
            <div class="thread-reply">
                <div class="reply-header">
                    <span class="author">@reply.Author</span>
                    <span class="timestamp">@FormatTimestamp(reply.SentAt)</span>
                </div>
                <div class="reply-content">@reply.Content</div>
            </div>
        }
    </div>

    <MessageInput Placeholder="Reply in thread..." ButtonLabel="Reply" OnSend="OnReply" />
</div>

@code {
    [Parameter, EditorRequired] public required Message RootMessage { get; set; }
    [Parameter, EditorRequired] public required List<Message> Replies { get; set; }
    [Parameter] public EventCallback<string> OnReply { get; set; }
    [Parameter] public EventCallback OnClose { get; set; }

    private static string FormatTimestamp(DateTime sentAt)
    {
        var diff = DateTime.Now - sentAt;
        if (diff.TotalMinutes < 1) return "just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes} min ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
        if (diff.TotalDays < 7) return $"{(int)diff.TotalDays}d ago";
        return sentAt.ToString("MMM d, yyyy");
    }
}

