.thread-panel {
    display: flex;
    flex-direction: column;
    height: 100%;
    background: #fafafa;
    border-left: 1px solid #ddd;
}

.thread-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 12px 16px;
    border-bottom: 1px solid #ddd;
}

.thread-header h3 {
    margin: 0;
    font-size: 1rem;
}

.close-btn {
    background: none;
    border: none;
    font-size: 1.2rem;
    cursor: pointer;
    padding: 4px 8px;
    border-radius: 4px;
    color: #666;
}

.close-btn:hover {
    background: #e8e8e8;
    color: #333;
}

.root-message-quote {
    padding: 12px 16px;
    border-bottom: 1px solid #eee;
    background: #f0f4f8;
}

.quote-author {
    font-weight: 700;
    font-size: 0.85rem;
    color: #333;
}

.quote-content {
    margin: 4px 0 0;
    font-size: 0.85rem;
    color: #555;
    white-space: pre-wrap;
}

.thread-messages {
    flex: 1;
    overflow-y: auto;
    padding: 8px 0;
}

.thread-reply {
    padding: 8px 16px;
}

.reply-header {
    display: flex;
    align-items: baseline;
    gap: 8px;
    margin-bottom: 2px;
}

.reply-header .author {
    font-weight: 700;
    font-size: 0.85rem;
    color: #1a1a1a;
}

.reply-header .timestamp {
    font-size: 0.72rem;
    color: #999;
}

.reply-content {
    font-size: 0.85rem;
    color: #333;
    line-height: 1.4;
    white-space: pre-wrap;
}

